2528	        if (mi >= M) break;
2529	        const int qpos = mi / rep, r = mi % rep;
2530	        const int head = hk * rep + r;
2531	        const TIn* qp = Q + (long)(q0 + qpos) * q_row + (long)head * q_head;
2532	#pragma unroll
2533	        for (int e = 0; e < per; ++e) qreg[mi][e] = to_float<TIn>(qp[lane * per + e]);
2534	#pragma unroll
2535	        for (int e = 0; e < perv; ++e) acc[mi][e] = 0.f;
