2594	// Flash-combine the per-split normalized partials into the final O/LSE.
2595	// The old kernel ran one WARP per (qidx,head) looping serially over splits, so for small
2596	// batch*heads only a few dozen warps were resident -> the cross-split reduce was DRAM-latency
2597	// starved (~40% of decode time, DRAM <2% on hd256). Here:
2598	//   * grid = (total_q*hq, NB): each (qidx,head) is split into NB ~64-elem HDV tiles -> NB x more
2599	//     resident blocks so the strided per-split O loads have enough warps to hide latency.
2600	//   * warp 0 builds the per-split softmax weights in smem (num_splits <= 64).
2601	//   * the split loop is unrolled x4 with 4 independent accumulators -> 4 O loads in flight/thread
2602	//     (memory-level parallelism), the real lever on a latency-bound reduce.
2603	constexpr int COMBINE_THREADS = 128;
2604	constexpr int combine_nb(int hdv) { return hdv / 64 > 0 ? hdv / 64 : 1; }
2605	template <typename TOut, int HDV>
2606	__global__ __launch_bounds__(COMBINE_THREADS) void combine_kernel(
2607	        const float* __restrict__ Opart, const float* __restrict__ LSEpart,
2608	        TOut* __restrict__ O, float* __restrict__ LSE,
2609	        int num_splits, int total_q, int hq, long o_row, long o_head) {
2610	    constexpr int NB = combine_nb(HDV);
2611	    constexpr int TILE = HDV / NB;
2612	    const int witem = blockIdx.x;
2613	    if (witem >= total_q * hq) return;
2614	    const int qidx = witem / hq, head = witem % hq;
2615	    const int tile = blockIdx.y, e0 = tile * TILE;
2616	    const int tid = threadIdx.x;
2617	
2618	    __shared__ float sw[64];          // per-split softmax weight (num_splits <= 64)
2619	    __shared__ float s_inv, s_lse;
2620	    if (tid < 32) {                   // warp 0: lmax -> weights -> denom
2621	        float lmax = -INFINITY;
2622	        for (int s = tid; s < num_splits; s += 32)
2623	            lmax = fmaxf(lmax, LSEpart[((long)s * hq + head) * total_q + qidx]);
2624	#pragma unroll
2625	        for (int o = 16; o > 0; o >>= 1) lmax = fmaxf(lmax, __shfl_xor_sync(0xffffffffu, lmax, o));
2626	        float denom = 0.f;
2627	        for (int s = tid; s < num_splits; s += 32) {
2628	            float lse = LSEpart[((long)s * hq + head) * total_q + qidx];
2629	            float w = (lmax > -INFINITY) ? __expf(lse - lmax) : 0.f;
2630	            sw[s] = w;
2631	            denom += w;
2632	        }
2633	#pragma unroll
2634	        for (int o = 16; o > 0; o >>= 1) denom += __shfl_xor_sync(0xffffffffu, denom, o);
2635	        if (tid == 0) { s_inv = denom > 0.f ? 1.f / denom : 0.f;
2636	                        s_lse = denom > 0.f ? (lmax + __logf(denom)) : -INFINITY; }
2637	    }
2638	    __syncthreads();
2639	    const float inv = s_inv;
2640	    const float* base = Opart + (((long)qidx * hq + head) * HDV);   // + s*sstride + e
2641	    const long sstride = (long)total_q * hq * HDV;
2642	    TOut* o = O + (long)qidx * o_row + (long)head * o_head;
2643	    // A zero-weight split contributes nothing -- but an EMPTY split (num_splits not dividing the
2644	    // key-tile count -> a trailing split starts past the last tile) never writes its Opart slice, so
2645	    // that memory is uninitialized at::empty (clean zeros on a fresh alloc, but NaN/inf when the
2646	    // caching allocator recycles a dirty pool). w==0 must therefore yield exactly 0, NOT 0*Opart
2647	    // (0*NaN=NaN). The select gates the garbage out; non-empty splits always store finite Opart.
2648	    for (int e = e0 + tid; e < e0 + TILE; e += COMBINE_THREADS) {
2649	        float a0 = 0.f, a1 = 0.f, a2 = 0.f, a3 = 0.f;
2650	        int s = 0;
2651	        for (; s + 4 <= num_splits; s += 4) {
2652	            float w0 = sw[s + 0], w1 = sw[s + 1], w2 = sw[s + 2], w3 = sw[s + 3];
2653	            a0 += w0 != 0.f ? w0 * base[(long)(s + 0) * sstride + e] : 0.f;
2654	            a1 += w1 != 0.f ? w1 * base[(long)(s + 1) * sstride + e] : 0.f;
2655	            a2 += w2 != 0.f ? w2 * base[(long)(s + 2) * sstride + e] : 0.f;
2656	            a3 += w3 != 0.f ? w3 * base[(long)(s + 3) * sstride + e] : 0.f;
2657	        }
2658	        float acc = (a0 + a1) + (a2 + a3);
2659	        for (; s < num_splits; ++s) { float w = sw[s]; acc += w != 0.f ? w * base[(long)s * sstride + e] : 0.f; }
2660	        o[e] = from_float<TOut>(acc * inv);
2661	    }
2662	    if (tid == 0 && tile == 0) LSE[(long)head * total_q + qidx] = s_lse;
2663	}
